import re


def slugify(s):
    s = s.lower()
    s = s.replace('\u00f5', 'o')
    s = re.sub(r'[^a-z0-9]+', '-', s)
    return s.strip('-')

import unicodedata


def slugify(s):
    s = s.lower()
    # Decompose unicode characters and drop combining marks
    # (e.g. 'õ' -> 'o' + tilde -> 'o').
    s = unicodedata.normalize('NFKD', s)
    s = ''.join(ch for ch in s if not unicodedata.category(ch).startswith('M'))
    out = []
    prev_sep = False
    for ch in s:
        if ch.isalnum():
            out.append(ch)
            prev_sep = False
        else:
            if not prev_sep:
                out.append('-')
            prev_sep = True
    return ''.join(out).strip('-')

